CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','INACTIVE','SUSPENDED');
CREATE TYPE "OrganizationType" AS ENUM ('CHOIR','PARISH','OTHER');
CREATE TYPE "EntityStatus" AS ENUM ('ACTIVE','INACTIVE','SUSPENDED');
CREATE TYPE "MembershipStatus" AS ENUM ('ACTIVE','INACTIVE','SUSPENDED');
CREATE TABLE "users" ("id" UUID PRIMARY KEY,"email" TEXT,"phone" TEXT,"passwordHash" TEXT NOT NULL,"firstName" TEXT NOT NULL,"lastName" TEXT NOT NULL,"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "users_email_key" ON "users"("email"); CREATE UNIQUE INDEX "users_phone_key" ON "users"("phone");
CREATE TABLE "organizations" ("id" UUID PRIMARY KEY,"name" TEXT NOT NULL,"type" "OrganizationType" NOT NULL DEFAULT 'CHOIR',"status" "EntityStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "choirs" ("id" UUID PRIMARY KEY,"organizationId" UUID NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"timezone" TEXT NOT NULL DEFAULT 'Africa/Kinshasa',"status" "EntityStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE INDEX "choirs_organizationId_idx" ON "choirs"("organizationId");
CREATE TABLE "memberships" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"choirId" UUID NOT NULL REFERENCES "choirs"("id") ON DELETE CASCADE,"status" "MembershipStatus" NOT NULL DEFAULT 'ACTIVE',"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("userId","choirId")); CREATE INDEX "memberships_choirId_status_idx" ON "memberships"("choirId","status");
CREATE TABLE "voice_sections" ("id" UUID PRIMARY KEY,"choirId" UUID NOT NULL REFERENCES "choirs"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("choirId","name"));
CREATE TABLE "member_profiles" ("membershipId" UUID PRIMARY KEY REFERENCES "memberships"("id") ON DELETE CASCADE,"postName" TEXT,"birthDate" DATE,"photoUrl" TEXT,"voiceSectionId" UUID REFERENCES "voice_sections"("id") ON DELETE SET NULL,"joinedChoirAt" TIMESTAMP(3),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "roles" ("id" UUID PRIMARY KEY,"organizationId" UUID REFERENCES "organizations"("id") ON DELETE CASCADE,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"isSystem" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("organizationId","code"));
CREATE TABLE "permissions" ("id" UUID PRIMARY KEY,"code" TEXT NOT NULL UNIQUE,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "role_permissions" ("roleId" UUID NOT NULL REFERENCES "roles"("id") ON DELETE CASCADE,"permissionId" UUID NOT NULL REFERENCES "permissions"("id") ON DELETE CASCADE,PRIMARY KEY("roleId","permissionId"));
CREATE TABLE "membership_roles" ("membershipId" UUID NOT NULL REFERENCES "memberships"("id") ON DELETE CASCADE,"roleId" UUID NOT NULL REFERENCES "roles"("id") ON DELETE CASCADE,PRIMARY KEY("membershipId","roleId"));
CREATE TABLE "refresh_tokens" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"replacedById" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "refresh_tokens_userId_idx" ON "refresh_tokens"("userId");
